        self.lon_max_spin.setRange(-180.0, 180.0)
        self.lon_max_spin.setDecimals(6)
        self.lon_max_spin.setValue(180.0)
        self.lon_max_spin.setSuffix("°")
        geo_layout.addRow("Lon max:", self.lon_max_spin)

